from taf.collectors.tshark.factory import TsharkCollectorFactorySelector
from taf.collectors.core import core
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class tshark(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_tshark_collector(self,
                                name,
                                options=None,
                                tshark_path=None,
                                target_file_name=None,
                                executor=None,
                                start_timeout=None,
                                stop_timeout=None,
                                sudo_password=None):
        """
        Create Tshark Collector from given configuration

        :param str name: name of collector
        :param str options: (optional) tshark options (except for "-w"), default: empty string
        :param str tshark_path: (optional) path of tshark executable, default value: "tshark"
        :param str target_file_name: (optional) file name part of the path under which the pcap file is
                                    stored locally during collect_collectors, default: "[collector_name].pcap"
        :param dict executor: (optional) setup info host, user, password,in dict format
        :param str sudo_password: (optional) password for sudo
        :param float start_timeout: (optional) start timeout is the time to wait after starting the process for the
                                    "Capturing on" message, as a float.
        :param float stop_timeout: (optional)  stop timeout is the time to wait after sending CTRL-C for the process
                                    to terminate, as a float.

        :return: TsharkCollector : created object of TsharkCollector
        """

        configuration = {'name': name}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["executor", "tshark_path", "target_file_name", "sudo_password", "options",
                                  "start_timeout", "stop_timeout"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
        logger.info("Creating Tshark Collector with alias name :" + name)
        tshark = TsharkCollectorFactorySelector().create(configuration=configuration, existing_arguments={})
        logger.info("Tshark Collector created successfully")
        self.set_alias(name, tshark)
